const real = EventTarget.prototype.addEventListener;
EventTarget.prototype.addEventListener = function (type, f, o) { if (type === "fzready" && typeof f === "function") { f.call(this, new Event(type)); return; } return real.call(this, type, f, o); };
const then = Promise.prototype.then;
Promise.prototype.then = function (f, r) { if (typeof f === "function" && f.name === "fzsync") { f(); return this; } return then.call(this, f, r); };
